mapper.update:
update t_process_instance_stage
set pis_status = #{toStatus}
    , pis_start_at = now()
    , pis_end_at = now()
where pis_id = #{id} and pis_status = #{fromStatus}

mapper.select:
select 
from t_process_instance_stage where pis_ref_id = #{refId}
limit 1

select ifnull(max(pis_round), 0)
from t_process_instance_stage
where pis_instance_id = #{instanceId}
  and pis_node_type in
#{t}
